// Collect required configuration from env; each missing item is a finding.
const required = ['SENDBLUE_API_BASE_URL','SENDBLUE_FROM_NUMBER','SENDBLUE_WEBHOOK_SECRET','ANTHROPIC_MODEL','SLACK_HANDOFF_CHANNEL_ID','SLACK_ALERTS_CHANNEL_ID','APPLICATION_LINK_BASE_URL','MESSAGING_TIMEZONE'];
const findings = [];
for (const k of required) {
  const v = $env[k];
  if (!v || String(v).includes('__REPLACE_ME__')) findings.push({ level: 'red', check: 'env:' + k, detail: 'missing or placeholder' });
}
if (!$env.SENDBLUE_EMMA_SEAT_ID) findings.push({ level: 'yellow', check: 'env:SENDBLUE_EMMA_SEAT_ID', detail: 'no bot seat configured — outbound seat attribution disabled (ASSUMPTIONS A-05/A-06)' });
return [{ json: { findings, started_at: new Date().toISOString() } }];

// Verify required agent_config keys exist and report kill-switch status.
const ctx = $('Init Check Context').first().json;
const rows = $input.all().map(i => i.json);
const findings = [...ctx.findings];
const cfg = {}; rows.forEach(r => { if (r.key) cfg[r.key] = r.value; });
const requiredKeys = ['global_ai_enabled','outbound_enabled','followups_enabled','status_lookup_enabled','test_mode','assistant_name','rate_limit_per_minute','test_allowlist_numbers'];
for (const k of requiredKeys) if (cfg[k] === undefined) findings.push({ level: 'red', check: 'agent_config:' + k, detail: 'missing key (seed from data-tables/seed-data.example.json)' });
if (rows.length === 0) findings.push({ level: 'red', check: 'agent_config', detail: 'table unreadable or empty — re-map Data Table node after import' });
findings.push({ level: 'info', check: 'kill_switch', detail: `global_ai_enabled=${cfg.global_ai_enabled ?? 'MISSING'} outbound_enabled=${cfg.outbound_enabled ?? 'MISSING'} test_mode=${cfg.test_mode ?? 'MISSING'}` });
if (cfg.test_mode === 'false' && $env.ALLOW_REAL_SEND !== 'true') findings.push({ level: 'red', check: 'send_gate', detail: 'test_mode=false but ALLOW_REAL_SEND!=true — sends will all fail closed' });
return [{ json: { findings, config: cfg } }];

// Aggregate probe outcomes into a single traffic-light report. Read-only; never messages customers.
const base = $('Verify Config + Kill Switch').first().json;
const findings = [...base.findings];
const probes = [
  { name: 'sendblue_lines', node: 'Sendblue: Get Lines', red: true },
  { name: 'sendblue_seats', node: 'Sendblue: Get Seats', red: false },
  { name: 'sendblue_webhooks', node: 'Sendblue: Get Webhooks', red: false },
  { name: 'salesforce_describe', node: 'Salesforce: Describe Lead', red: true },
  { name: 'slack_auth', node: 'Slack: Auth Check', red: true }
];
const items = $input.all().map(i => i.json);
for (const p of probes) {
  let out = null;
  try { out = $(p.node).first().json; } catch (e) { out = null; }
  const status = out && (out.statusCode || out.status);
  const ok = status >= 200 && status < 300;
  if (!ok) findings.push({ level: p.red ? 'red' : 'yellow', check: p.name, detail: `probe failed (HTTP ${status ?? 'error'})` });
  else findings.push({ level: 'info', check: p.name, detail: 'OK' });
  if (p.name === 'sendblue_lines' && ok) {
    const body = out.body || out;
    const lines = JSON.stringify(body);
    if ($env.SENDBLUE_FROM_NUMBER && !lines.includes(String($env.SENDBLUE_FROM_NUMBER))) {
      findings.push({ level: 'red', check: 'from_number', detail: 'SENDBLUE_FROM_NUMBER not found among account lines' });
    }
  }
  if (p.name === 'sendblue_seats' && ok && $env.SENDBLUE_EMMA_SEAT_ID) {
    const seats = JSON.stringify(out.body || out);
    if (!seats.includes(String($env.SENDBLUE_EMMA_SEAT_ID))) findings.push({ level: 'yellow', check: 'emma_seat', detail: 'configured SENDBLUE_EMMA_SEAT_ID not found in seats response' });
  }
  if (p.name === 'sendblue_webhooks' && ok) {
    const hooks = JSON.stringify(out.body || out);
    if (!hooks.includes('/webhook/sendblue/inbound')) findings.push({ level: 'yellow', check: 'inbound_webhook', detail: 'receive webhook for /webhook/sendblue/inbound not registered yet (docs/SENDBLUE-SETUP.md)' });
  }
  if (p.name === 'salesforce_describe' && ok) {
    // Field-map verification: required logical mappings must not be UNMAPPED.
    const mapRaw = $env.SF_FIELD_MAP_JSON;
    if (!mapRaw) findings.push({ level: 'red', check: 'field_map', detail: 'SF_FIELD_MAP_JSON env not set — paste resolved config/salesforce-field-map.json (docs/N8N-SETUP.md)' });
    else {
      try {
        const map = JSON.parse(mapRaw);
        const fieldNames = ((out.body || out).fields || []).map(f => f.name);
        for (const [k, s] of Object.entries(map.mappings || {})) {
          if (s.required && (s.field === 'UNMAPPED' || s.object === 'UNMAPPED')) findings.push({ level: 'red', check: 'field_map:' + k, detail: 'required mapping UNMAPPED' });
          else if (s.object === 'Lead' && s.field !== 'UNMAPPED' && fieldNames.length && !fieldNames.includes(s.field)) findings.push({ level: 'red', check: 'field_map:' + k, detail: `Lead.${s.field} does not exist in org` });
        }
      } catch (e) { findings.push({ level: 'red', check: 'field_map', detail: 'SF_FIELD_MAP_JSON is not valid JSON' }); }
    }
  }
}
const reds = findings.filter(f => f.level === 'red');
const yellows = findings.filter(f => f.level === 'yellow');
const overall = reds.length ? 'RED' : yellows.length ? 'YELLOW' : 'GREEN';
return [{ json: { overall, red_count: reds.length, yellow_count: yellows.length, findings, checked_at: new Date().toISOString() } }];
